// === Tab: mySketch ===
// For the #WCCChallenge «Construction» (join the discord! https://discord.gg/S8c7qcjw2b)

// Brutalist construction in 2D with two-point perspective.

let blocks = [];
let progressivePainter = null;

// Parameter ranges – sampled once per structure in regenerate()
const RANGES = {
	horizonFrac: [0.12, 0.45],
	vpDist: [0.65, 1.15],
	lightAzim: [0, 1],
	lightElev: [0.25, 0.75],
	lightAmbient: [0.08, 0.28],
	lightDistance: [500, 1200],
	measureProb: [0.15, 0.65],
	measureEdgeFrac: [1.5, 7],
	measureOffsetFrac: [1.5, 7],
	textureWatercolor: [0.5, 0.98],
	textureHatching: [0.35, 0.85],
	textureSubdivision: [0.2, 0.75],
	watercolorOpacity: [0.008, 0.035],
	watercolorRadius: [18, 45],
	watercolorRadiusJitter: [4, 18],
	watercolorCoverage: [60, 160],
	watercolorBaseOpacity: [0.85, 0.95],
	watercolorHRange: [2, 12],
	watercolorSRange: [5, 18],
	watercolorBRange: [5, 18],
	hatchOpacity: [0.02, 0.12],
	hatchLineWeight: [2.5, 8],
	hatchCrossWeight: [0.25, 0.9],
	subdivisionLineWeight: [0.35, 1.1],
	subdivisionDepth: [2, 8],
	outlineWeightMin: [0.5, 1],
	outlineWeightMax: [1.2, 2.5],
	coreCount: [8, 22],
	unit: [22, 42],
	coreW: [4, 9],
	coreD: [2.5, 6],
	coreMinH: [0.9, 1.4],
	coreMaxH: [1.6, 2.6],
	attachPerCoreMin: [0, 3],
	attachPerCoreMax: [3, 7],
	wildChance: [0.15, 0.45],
	satelliteChance: [0.05, 0.28],
	maxBlocks: [100, 220],
};

// Per-structure params (set in regenerate)
let params = {};
let worldMinY = 0, worldMaxY = 0;
let eyeY = 0;
const camDist = 1000;
let worldScale = 0.5;
let projScale = 1;
let structureCenterX = 0, structureCenterY = 0;

// Persisted per structure (set in regenerate)
let structureMeasure = { edgeFrac: 0.25, offsetFrac: 0.12 };

// Face definitions: [vertex indices], tone multiplier for shading
const BOX_FACES = [
	{ verts: [0, 1, 2, 3], tone: 0.82 }, // bottom (ny)
	{ verts: [4, 5, 6, 7], tone: 1.0 },  // top (py)
	{ verts: [0, 1, 5, 4], tone: 0.95 }, // front (nz)
	{ verts: [2, 3, 7, 6], tone: 0.88 }, // back (pz)
	{ verts: [0, 3, 7, 4], tone: 0.92 }, // left (nx)
	{ verts: [1, 2, 6, 5], tone: 0.95 }, // right (px)
];

const AVAILABLE_PALETTES = [
	["#fffcf2","#ccc5b9","#403d39","#252422","#eb5e28"],
  ["#000000","#14213d","#fca311","#e5e5e5","#ffffff"],
	["#0b090a", "#161a1d", "#660708", "#a4161a", "#ba181b", "#e5383b", "#b1a7a6", "#d3d3d3", "#f5f3f4", "#ffffff"],
	["#353535","#3c6e71","#ffffff","#d9d9d9","#284b63"],
	["#197278","#ffffff","#f5cb5c","#242423","#333533"],
	["#ef6461","#e4b363","#e8e9eb","#e0dfd5","#313638"],
	["#FFFFFF", "#FFFFFF", "#ffe169","#a47e1b","#805b10", "#000000", "#000000"],
	["#f8f9fa","#dee2e6","#adb5bd","#495057","#212529"],
	["#010653","#036cbd","#336699","#e1e7e9","#d6dcda","#a7aeb4","#a2abaa"],
	["#000000","#1a1a1a","#333333","#bfcc0d","#edff00","#c9ad95","#e4d6ca","#ffffff"],
	['#FFFFFF',"#edede9","#d6ccc2","#f5ebe0","#e3d5ca","#d5bdaf", '#582f0e'],
	["#1c1c1c","#c8d5b9","#adc178","#eef0f2","#ffffff", '#245501'],
]
let PALETTE_COLORS = AVAILABLE_PALETTES[0];
const OUTLINE_HEX = "#23262a";
const MEASURE_HEX = "#323232";
const HATCH_SHADOW_COLOR = "#1a1a1a";
const SUBDIVISION_LINE_COLOR = "#2a2a2e";
const WATERCOLOR_GRAYSCALE_S_THRESHOLD = 0;
const WATERCOLOR_GRAYSCALE_B_MIN = 8;
const WATERCOLOR_GRAYSCALE_B_MAX = 95;

const BASE_STRUCT_KIND_WEIGHTS = {
	box: 50, floor_columns: 20, hollow_window: 10, stairs: 10,
	stacked: 10, split: 8, tunnel: 5, protruding: 8,
};
let structKindWeights = { ...BASE_STRUCT_KIND_WEIGHTS };

// -----------------------------------------------------------------------------
// Entry point
// -----------------------------------------------------------------------------

function rr(name) {
	const [a, b] = RANGES[name];
	return typeof a === "number" ? random(a, b) : a[floor(random(a.length))];
}

async function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 1);
	regenerate();
}

function draw() {
	computeStructureBounds();
	eyeY = lerp(worldMaxY, worldMinY, params.horizonFrac);
	cam = solveCameraFromVPs(-width * params.vpDist, width * params.vpDist, height / 2);
	computeFitAndCenter();

	if (!progressivePainter) {
		noStroke();
		progressivePainter = createProgressivePainter();
	}
	const result = progressivePainter.next();
	if (result.done) {
		let img = get();
		let fipFilter = createFilterShader(fip.sketch);
		let deformFilter = createFilterShader(fip.deform);
		let ditherFilter = createFilterShader(fip.dithering);
		deformFilter.setUniform('deformationAmount', 0.01);
		ditherFilter.setUniform('threshold', 0.3);
		ditherFilter.setUniform('dotSize', 0.001);
		filter(fipFilter);
		filter(deformFilter);
		// filter(ditherFilter);
		let img2 = get();
		clear();
		background("#f8f8f8");
		push();
		translate(width / 2, height / 2);
		scale(1.10);
		tint(255, 0.08);
		imageMode(CENTER);
		image(img2, 0, 0);
		pop();
		tint(255, 1);
		image(img, 0, 0);
		drawMeasurementLinesOverlay();
		noLoop();
		return;
	}
}

// -----------------------------------------------------------------------------
// Regeneration
// -----------------------------------------------------------------------------

function regenerate() {
	params = {
		horizonFrac: rr("horizonFrac"),
		vpDist: rr("vpDist"),
		lightAzim: rr("lightAzim"),
		lightElev: rr("lightElev"),
		lightAmbient: rr("lightAmbient"),
		lightDistance: rr("lightDistance"),
		measureProb: rr("measureProb"),
		textureWatercolor: rr("textureWatercolor"),
		textureHatching: rr("textureHatching"),
		textureSubdivision: rr("textureSubdivision"),
		watercolorOpacity: rr("watercolorOpacity"),
		watercolorRadius: rr("watercolorRadius"),
		watercolorRadiusJitter: rr("watercolorRadiusJitter"),
		watercolorCoverage: rr("watercolorCoverage"),
		watercolorBaseOpacity: rr("watercolorBaseOpacity"),
		watercolorHRange: rr("watercolorHRange"),
		watercolorSRange: rr("watercolorSRange"),
		watercolorBRange: rr("watercolorBRange"),
		hatchOpacity: rr("hatchOpacity"),
		hatchLineWeight: rr("hatchLineWeight"),
		hatchCrossWeight: rr("hatchCrossWeight"),
		subdivisionLineWeight: rr("subdivisionLineWeight"),
		subdivisionDepth: floor(rr("subdivisionDepth")),
		outlineWeight: [rr("outlineWeightMin"), rr("outlineWeightMax")],
	};

	structureMeasure.edgeFrac = random(RANGES.measureEdgeFrac[0], RANGES.measureEdgeFrac[1]);
	structureMeasure.offsetFrac = random(RANGES.measureOffsetFrac[0], RANGES.measureOffsetFrac[1]);

	PALETTE_COLORS = random(AVAILABLE_PALETTES);

	structKindWeights = Object.fromEntries(
		Object.entries(BASE_STRUCT_KIND_WEIGHTS).map(([k, v]) => [k, Math.max(1, v * random(0.5, 1.8))])
	);

	blocks = generateStructure({
		coreCount: floor(rr("coreCount")),
		unit: rr("unit"),
		coreW: rr("coreW"),
		coreD: rr("coreD"),
		coreMinH: rr("coreMinH"),
		coreMaxH: rr("coreMaxH"),
		attachPerCoreMin: floor(rr("attachPerCoreMin")),
		attachPerCoreMax: floor(rr("attachPerCoreMax")),
		wildChance: rr("wildChance"),
		satelliteChance: rr("satelliteChance"),
		maxBlocks: floor(rr("maxBlocks")),
	});
	assignMeasurementLines(blocks);
	progressivePainter = null;
	loop();
}

function assignMeasurementLines(blocks) {
	for (const block of blocks) {
		if (random() >= params.measureProb) {
			block._measure = null;
			continue;
		}
		const faceIndices = shuffle([...Array(BOX_FACES.length).keys()], true);
		block._measure = [];
		const nFaces = floor(random(1, 3));
		for (let f = 0; f < nFaces; f++) {
			const faceIdx = faceIndices[f];
			const edgeIdx = floor(random(4));
			const nLines = floor(random(2, 5));
			const drawEdges = shuffle([0, 1, 2, 3], true).slice(0, nLines).sort((a, b) => a - b);
			const protrudeStart = random() < 0.5;
			const protrudeEnd = random() < 0.5;
			const protrudePx = random(10, 30);
			block._measure.push({ faceIdx, edgeIdx, drawEdges, protrudeStart, protrudeEnd, protrudePx });
		}
	}
}

// -----------------------------------------------------------------------------
// Drawing pipeline: progressive painter, faces, measurement overlay
// -----------------------------------------------------------------------------

function* createProgressivePainter() {
	const allFaces = [];
	for (const block of blocks) {
		const geom = getStructureGeometry(block);
		const projected = geom.vertices.map(v => project(v));
		if (projected.some(p => p === null)) continue;
		for (const face of geom.faces) {
			allFaces.push({ geom, face, projected, textures: pickTextures() });
		}
	}
	allFaces.sort((a, b) =>
		faceDepthFromVerts(b.geom.vertices, b.face) - faceDepthFromVerts(a.geom.vertices, a.face)
	);
	let counter = 0;
	for (const { geom, face, projected, textures } of allFaces) {
		drawFaceFill(geom, face, projected, textures);
		drawFaceOutline(geom, face, projected);
		counter++;
		if (counter % 20 === 0) yield 1;
	}
}

function drawFaceFill(geom, face, projected, textures) {
	const faceCenter = faceCenterWorld(geom.vertices, face);
	const faceNormal = faceNormalWorld(geom.vertices, face);
	const hsb = getSurfaceColor({ faceCenter, faceNormal, face, geom });
	noStroke();
	fill(hsb.h, hsb.s, hsb.b, params.watercolorBaseOpacity);
	beginShape();
	const order = isBackFace(geom.vertices, face) ? [...face.vertIndices].reverse() : face.vertIndices;
	const poly = order.map(i => projected[i]);
	for (const p of poly) vertex(p.x, p.y);
	if (face.holeIndices) {
		beginContour();
		if (isBackFace(geom.vertices, face)) {
			for (const j of face.holeIndices) vertex(projected[j].x, projected[j].y);
		} else {
			for (let i = face.holeIndices.length - 1; i >= 0; i--) {
				vertex(projected[face.holeIndices[i]].x, projected[face.holeIndices[i]].y);
			}
		}
		endContour();
	}
	endShape(CLOSE);
	if (textures.watercolor) applyWatercolorTexture(geom, face, projected, hsb);
	if (textures.hatching) applyShadowHatching(geom, face, projected);
	if (textures.subdivision) applySubdivisionTexture(geom, face, projected);
}

function drawFaceOutline(geom, face, projected) {
	const oc = hexToHSB(OUTLINE_HEX);
	stroke(oc.h, oc.s, oc.b, 120);
	noFill();
	const order = isBackFace(geom.vertices, face) ? [...face.vertIndices].reverse() : face.vertIndices;
	const pts = order.map(i => projected[i]);
	for (let i = 0; i < pts.length; i++) {
		strokeWeight(random(...params.outlineWeight));
		const j = (i + 1) % pts.length;
		line(pts[i].x, pts[i].y, pts[j].x, pts[j].y);
	}
	if (face.holeIndices) {
		const holePts = face.holeIndices.map(ii => projected[ii]);
		for (let i = 0; i < holePts.length; i++) {
			const j = (i + 1) % holePts.length;
			strokeWeight(random(...params.outlineWeight));
			line(holePts[i].x, holePts[i].y, holePts[j].x, holePts[j].y);
		}
	}
	noStroke();
}

function drawMeasurementLinesOverlay() {
	blocks.sort((a, b) => blockDepth(b) - blockDepth(a));
	for (const b of blocks) {
		if (b._measure && b.structureKind === "box") {
			const geom = getStructureGeometry(b);
			drawMeasurementLines(b, geom.vertices);
		}
	}
}

function drawMeasurementLines(block, corners) {
	const structCenter = createVector(0, (worldMinY + worldMaxY) / 2, 0);
	const minDim = Math.min(block.size.x, block.size.y, block.size.z);
	const offsetDist = minDim * structureMeasure.offsetFrac;
	for (const { faceIdx, edgeIdx, drawEdges, protrudeStart, protrudeEnd, protrudePx } of block._measure) {
		const face = BOX_FACES[faceIdx];
		const vs = face.verts;
		const v0 = corners[vs[0]], v1 = corners[vs[1]], v2 = corners[vs[2]], v3 = corners[vs[3]];
		const e1 = p5.Vector.sub(v1, v0);
		const e2 = p5.Vector.sub(v3, v0);
		const N = p5.Vector.cross(e1, e2).normalize();
		const edges = [[v0, v1], [v1, v2], [v2, v3], [v3, v0]];
		const [a, b] = edges[edgeIdx];
		const E = p5.Vector.sub(b, a);
		const mid = p5.Vector.add(a, b).mult(0.5);
		const P = p5.Vector.cross(N, E).normalize();
		if (P.mag() < 0.01) continue;
		const towardCenter = p5.Vector.sub(structCenter, mid);
		if (p5.Vector.dot(P, towardCenter) < 0) P.mult(-1);
		const elen = E.mag();
		if (elen < 1) continue;
		const halfLen = elen * structureMeasure.edgeFrac * 0.5;
		const Eunit = E.copy().normalize();
		const p0 = p5.Vector.add(mid, Eunit.copy().mult(-halfLen));
		const p1 = p5.Vector.add(mid, Eunit.copy().mult(halfLen));
		const p2 = p5.Vector.add(p1, P.copy().mult(offsetDist));
		const p3 = p5.Vector.add(p0, P.copy().mult(offsetDist));
		const pts = [p0, p1, p2, p3].map(p => project(p));
		if (pts.some(p => !p)) continue;
		const mc = hexToHSB(MEASURE_HEX);
		stroke(mc.h, mc.s, mc.b, 220);
		strokeWeight(0.8);
		noFill();
		const rectEdges = [[0, 1], [1, 2], [2, 3], [3, 0]];
		for (const ei of drawEdges) {
			const [i, j] = rectEdges[ei];
			let x0 = pts[i].x, y0 = pts[i].y, x1 = pts[j].x, y1 = pts[j].y;
			const dx = x1 - x0, dy = y1 - y0;
			const len = sqrt(dx * dx + dy * dy) || 1;
			const ux = dx / len, uy = dy / len;
			if (protrudeStart) { x0 -= ux * protrudePx; y0 -= uy * protrudePx; }
			if (protrudeEnd) { x1 += ux * protrudePx; y1 += uy * protrudePx; }
			drawingContext.setLineDash([8, 4]);
			line(x0, y0, x1, y1);
		}
	}
	noStroke();
}

function setRandomDash() {
	let n = floor(random(2, 5)) * 2;
	let dash = [];
	for (let i = 0; i < n; i++) {
		dash.push(random(2, 6));
		dash.push(random(2, 6));
	}
	drawingContext.setLineDash(dash);
}

// -----------------------------------------------------------------------------
// Textures: watercolor, hatching, subdivision
// -----------------------------------------------------------------------------

/** Apply watercolor-like texture: shape mask + uniform random dots. */
function applyWatercolorTexture(geom, face, projected, baseHSB) {
	const { h, s, b } = baseHSB;
	const order = isBackFace(geom.vertices, face) ? [...face.vertIndices].reverse() : face.vertIndices;
	const poly = order.map(i => projected[i]);
	if (poly.length < 3) return;
	let area = 0;
	for (let i = 1; i < poly.length - 1; i++) area += abs(triangleArea2(poly[0], poly[i], poly[i + 1]));
	area /= 2;
	const rAvg = params.watercolorRadius;
	const circleArea = PI * rAvg * rAvg;
	const n = Math.max(3, floor((area / circleArea) * params.watercolorCoverage));
	const margin = rAvg;
	const polyExp = expandPolyByMargin(poly, margin);
	push();
	beginClip();
	beginShape();
	for (const p of poly) vertex(p.x, p.y);
	if (face.holeIndices) {
		beginContour();
		if (isBackFace(geom.vertices, face)) {
			for (const j of face.holeIndices) vertex(projected[j].x, projected[j].y);
		} else {
			for (let i = face.holeIndices.length - 1; i >= 0; i--) {
				vertex(projected[face.holeIndices[i]].x, projected[face.holeIndices[i]].y);
			}
		}
		endContour();
	}
	endShape(CLOSE);
	endClip();
	noStroke();
	const canVaryHue = s >= WATERCOLOR_GRAYSCALE_S_THRESHOLD &&
		b >= WATERCOLOR_GRAYSCALE_B_MIN && b <= WATERCOLOR_GRAYSCALE_B_MAX;
	const choices = canVaryHue ? [0, 1, 2] : [1, 2];
	for (let i = 0; i < n; i++) {
		const which = random(choices);
		let nh = h, ns = s, nb = b;
		if (which === 0) nh = constrain(h + random(-params.watercolorHRange, params.watercolorHRange), 0, 360);
		else if (which === 1) ns = constrain(s + random(-params.watercolorSRange, params.watercolorSRange), 0, 100);
		else nb = constrain(b + random(-params.watercolorBRange, params.watercolorBRange), 0, 100);
		fill(nh, ns, nb, params.watercolorOpacity);
		const radius = params.watercolorRadius + random(-params.watercolorRadiusJitter, params.watercolorRadiusJitter);
		const p = randomPointInPoly(polyExp);
		ellipse(p.x, p.y, radius * 2, radius * 2);
	}
	pop();
}

/** Draw shadow hatching: parallel and cross-hatch with density gradient toward shadow. */
function applyShadowHatching(geom, face, projected) {
	const order = isBackFace(geom.vertices, face) ? [...face.vertIndices].reverse() : face.vertIndices;
	const poly = order.map(i => projected[i]);
	if (poly.length < 3) return;
	const lightPosWorld = getLightPositionWorld();
	let lightPos2D = project(lightPosWorld);
	if (!lightPos2D) {
		const cx = poly.reduce((s, p) => s + p.x, 0) / poly.length;
		const cy = poly.reduce((s, p) => s + p.y, 0) / poly.length;
		lightPos2D = createVector(cx - 200, cy - 200);
	}
	const faceCenter2D = createVector(
		poly.reduce((s, p) => s + p.x, 0) / poly.length,
		poly.reduce((s, p) => s + p.y, 0) / poly.length
	);
	let shadowDir = p5.Vector.sub(faceCenter2D, lightPos2D);
	if (shadowDir.mag() < 1) return;
	shadowDir.normalize();
	const E0 = p5.Vector.sub(poly[1], poly[0]);
	const E1 = poly.length >= 4 ? p5.Vector.sub(poly[3], poly[0]) : p5.Vector.sub(poly[2], poly[0]);
	const len0 = E0.mag(), len1 = E1.mag();
	if (len0 < 1 || len1 < 1) return;
	const dir0 = E0.copy().div(len0);
	const dir1 = E1.copy().div(len1);
	const perp0 = createVector(-dir0.y, dir0.x);
	const perp1 = createVector(-dir1.y, dir1.x);
	const dot0 = abs(perp0.dot(shadowDir));
	const dot1 = abs(perp1.dot(shadowDir));
	const hatchDir = dot0 >= dot1 ? dir0 : dir1;
	let perpHatch = createVector(-hatchDir.y, hatchDir.x);
	if (perpHatch.dot(shadowDir) < 0) perpHatch.mult(-1);
	const projs = poly.map(p => p.x * perpHatch.x + p.y * perpHatch.y);
	const minP = Math.min(...projs), maxP = Math.max(...projs);
	const span = maxP - minP;
	if (span < 4) return;
	const hc = hexToHSB(HATCH_SHADOW_COLOR);
	stroke(hc.h, hc.s, hc.b, params.hatchOpacity);
	strokeWeight(params.hatchLineWeight * random(0.5, 1));
	noFill();
	push();
	beginClip();
	beginShape();
	for (const p of poly) vertex(p.x, p.y);
	if (face.holeIndices) {
		beginContour();
		if (isBackFace(geom.vertices, face)) {
			for (const j of face.holeIndices) vertex(projected[j].x, projected[j].y);
		} else {
			for (let i = face.holeIndices.length - 1; i >= 0; i--) {
				vertex(projected[face.holeIndices[i]].x, projected[face.holeIndices[i]].y);
			}
		}
		endContour();
	}
	endShape(CLOSE);
	endClip();
	const nLines = Math.max(8, floor(span / 3));
	for (let i = 0; i < nLines; i++) {
		const t = 1 - pow(random(), 1.5);
		const pVal = minP + t * span;
		const pts = linePolygonIntersect(poly, perpHatch, pVal, hatchDir);
		for (let j = 0; j < pts.length - 1; j += 2) {
			setRandomDash();
			line(pts[j].x, pts[j].y, pts[j + 1].x, pts[j + 1].y);
		}
	}
	let perpHatch2 = dot0 >= dot1 ? perp1 : perp0;
	if (perpHatch2.dot(shadowDir) < 0) perpHatch2 = perpHatch2.copy().mult(-1);
	const hatchDir2 = createVector(-perpHatch2.y, perpHatch2.x);
	const projs2 = poly.map(p => p.x * perpHatch2.x + p.y * perpHatch2.y);
	const minP2 = Math.min(...projs2), maxP2 = Math.max(...projs2);
	const span2 = maxP2 - minP2;
	if (span2 >= 4) {
		strokeWeight(params.hatchCrossWeight);
		const nLines2 = Math.max(6, floor(span2 / 4));
		for (let i = 0; i < nLines2; i++) {
			const t = 1 - pow(random(), 1.5);
			const pVal = minP2 + t * span2;
			const pts = linePolygonIntersect(poly, perpHatch2, pVal, hatchDir2);
			for (let j = 0; j < pts.length - 1; j += 2) {
				line(pts[j].x, pts[j].y, pts[j + 1].x, pts[j + 1].y);
			}
		}
	}
	noStroke();
	pop();
}

/** Recursively subdivide parallelogram and collect split-line segments. */
function subdivideQuadRec(quad, depth, lines) {
	if (depth <= 0 || quad.length !== 4) return;
	const E0 = p5.Vector.sub(quad[1], quad[0]);
	const E1 = p5.Vector.sub(quad[3], quad[0]);
	const len0 = E0.mag(), len1 = E1.mag();
	if (len0 < 1 || len1 < 1) return;
	const dir0 = E0.copy().div(len0);
	const dir1 = E1.copy().div(len1);
	const perp0 = createVector(-dir0.y, dir0.x);
	const perp1 = createVector(-dir1.y, dir1.x);
	const axis = floor(random(2));
	const perp = axis === 0 ? perp0 : perp1;
	const dir = axis === 0 ? dir0 : dir1;
	const projs = quad.map(p => p.x * perp.x + p.y * perp.y);
	const minP = Math.min(...projs), maxP = Math.max(...projs);
	const span = maxP - minP;
	if (span < 6) return;
	const t = 0.3 + random(0.4);
	const pVal = minP + t * span;
	const seg = linePolygonIntersect(quad, perp, pVal, dir);
	if (seg.length >= 2) lines.push([seg[0], seg[seg.length - 1]]);
	const parts = splitQuadByLine(quad, perp, pVal);
	if (!parts) return;
	const [p0, p1] = parts;
	subdivideQuadRec(random() < 0.5 ? p0 : p1, depth - 1, lines);
}

// -----------------------------------------------------------------------------
// Colors and appearance
// -----------------------------------------------------------------------------

function hexToHSB(hex) {
	const c = color(hex);
	return { h: hue(window.color(c)), s: saturation(window.color(c)), b: brightness(window.color(c)) };
}

function weightedRandom(weights) {
	const entries = Object.entries(weights);
	const total = entries.reduce((s, [, w]) => s + w, 0);
	let r = random(total);
	for (const [k, w] of entries) {
		r -= w;
		if (r <= 0) return k;
	}
	return entries[entries.length - 1][0];
}

function pickStructureKind() {
	return weightedRandom(structKindWeights);
}

function makeStructParams(block) {
	const k = block.structureKind;
	const p = block.pos, w = block.size.x / 2, d = block.size.z / 2;
	if (k === "floor_columns") {
		const nCols = 2 + floor(random(4));
		const cols = [];
		for (let i = 0; i < nCols; i++) {
			cols.push({
				x: p.x - w + (2 * w) * (0.15 + 0.7 * random()),
				z: p.z - d + (2 * d) * (0.15 + 0.7 * random()),
			});
		}
		let hasFloor = random() < random(0.5, 0.85);
		let hasCeiling = random() < random(0.5, 0.85);
		if (!hasFloor && !hasCeiling) {
			if (random() < 0.5) hasFloor = true;
			else hasCeiling = true;
		}
		return { nCols, cols, hasFloor, hasCeiling };
	}
	if (k === "stairs") return { nSteps: 2 + floor(random(5)) };
	if (k === "stacked") return {
		botFrac: 0.4 + random(0.35),
		sizeFrac: 0.45 + random(0.45),
	};
	if (k === "split") return {
		splitAxis: random() < 0.5 ? "x" : "z",
		frac: 0.3 + random(0.35),
	};
	if (k === "hollow_window") return {
		winW: block.size.x * (0.2 + random(0.35)),
		winH: block.size.y * (0.25 + random(0.4)),
	};
	if (k === "tunnel") return { axis: random() < 0.5 ? "x" : "z" };
	if (k === "protruding") return {
		nSides: 2 + floor(random(3)),
		wallFrac: 0.4 + random(0.4),
		protrudeFrac: 0.05 + random(0.12),
	};
	return {};
}

/**
 * Returns { vertices, faces } for a block. Faces: { vertIndices, tone, holeIndices? }.
 */
function getStructureGeometry(block) {
	const k = block.structureKind || "box";
	if (k === "box") return getBoxGeometry(block);
	if (k === "floor_columns") return getFloorColumnsGeometry(block);
	if (k === "hollow_window") return getHollowWindowGeometry(block);
	if (k === "stairs") return getStairsGeometry(block);
	if (k === "stacked") return getStackedGeometry(block);
	if (k === "split") return getSplitGeometry(block);
	if (k === "tunnel") return getTunnelGeometry(block);
	if (k === "protruding") return getProtrudingGeometry(block);
	return getBoxGeometry(block);
}

function boxVerts(pos, sx, sy, sz) {
	return [
		createVector(pos.x - sx, pos.y - sy, pos.z - sz),
		createVector(pos.x + sx, pos.y - sy, pos.z - sz),
		createVector(pos.x + sx, pos.y - sy, pos.z + sz),
		createVector(pos.x - sx, pos.y - sy, pos.z + sz),
		createVector(pos.x - sx, pos.y + sy, pos.z - sz),
		createVector(pos.x + sx, pos.y + sy, pos.z - sz),
		createVector(pos.x + sx, pos.y + sy, pos.z + sz),
		createVector(pos.x - sx, pos.y + sy, pos.z + sz),
	];
}

function getBoxGeometry(block) {
	const p = block.pos;
	const sx = block.size.x / 2, sy = block.size.y / 2, sz = block.size.z / 2;
	const verts = boxVerts(p, sx, sy, sz);
	const faces = BOX_FACES.map(f => ({ vertIndices: [...f.verts], tone: f.tone }));
	return { vertices: verts, faces };
}

function getFloorColumnsGeometry(block) {
	const p = block.pos;
	const h = block.size.y, w = block.size.x / 2, d = block.size.z / 2;
	const slabThick = h * 0.2;
	const { nCols, cols, hasFloor, hasCeiling } = block._structParams;
	const colSize = Math.min(block.size.x, block.size.z) * 0.12;

	const vertices = [];
	const faces = [];
	let voff = 0;

	const blockBottom = p.y - h / 2;
	const blockTop = p.y + h / 2;

	let colBaseY = blockBottom;
	let colTopY = blockTop;

	if (hasFloor) {
		const floorY = blockBottom + slabThick / 2;
		const floorPos = createVector(p.x, floorY, p.z);
		const floorVerts = boxVerts(floorPos, w, slabThick / 2, d);
		vertices.push(...floorVerts);
		const floorFaces = [
			[0, 1, 2, 3], [4, 5, 6, 7], [0, 1, 5, 4], [2, 3, 7, 6], [0, 3, 7, 4], [1, 2, 6, 5],
		].map((v, i) => ({ vertIndices: v.map(ii => voff + ii), tone: BOX_FACES[i].tone }));
		faces.push(...floorFaces);
		voff += 8;
		colBaseY = blockBottom + slabThick;
	}
	if (hasCeiling) {
		colTopY = blockTop - slabThick;
	}

	const colH = colTopY - colBaseY;
	if (colH > 0 && nCols > 0) {
		const colCenterY = (colBaseY + colTopY) / 2;
		for (let i = 0; i < nCols; i++) {
			const colPos = createVector(cols[i].x, colCenterY, cols[i].z);
			const colV = boxVerts(colPos, colSize / 2, colH / 2, colSize / 2);
			vertices.push(...colV);
			for (const f of BOX_FACES) {
				faces.push({ vertIndices: f.verts.map(ii => voff + ii), tone: f.tone * 1.02 });
			}
			voff += 8;
		}
	}

	if (hasCeiling) {
		const ceilingY = blockTop - slabThick / 2;
		const ceilingPos = createVector(p.x, ceilingY, p.z);
		const ceilingVerts = boxVerts(ceilingPos, w, slabThick / 2, d);
		vertices.push(...ceilingVerts);
		const ceilingFaces = [
			[0, 1, 2, 3], [4, 5, 6, 7], [0, 1, 5, 4], [2, 3, 7, 6], [0, 3, 7, 4], [1, 2, 6, 5],
		].map((v, i) => ({ vertIndices: v.map(ii => voff + ii), tone: BOX_FACES[i].tone }));
		faces.push(...ceilingFaces);
	}
	return { vertices, faces };
}

function getStairsGeometry(block) {
	const p = block.pos;
	const w = block.size.x, h = block.size.y, d = block.size.z;
	const { nSteps } = block._structParams;
	const stepH = h / nSteps;
	const stepD = d / nSteps;
	const vertices = [];
	const faces = [];
	for (let i = 0; i < nSteps; i++) {
		const stepY = p.y - h / 2 + stepH * (i + 0.5);
		const stepZ = p.z - d / 2 + stepD * (i + 0.5);
		const stepPos = createVector(p.x, stepY, stepZ);
		const stepSz = createVector(w / 2, stepH / 2, stepD / 2);
		const v = boxVerts(stepPos, stepSz.x, stepSz.y, stepSz.z);
		const voff = vertices.length;
		vertices.push(...v);
		for (const f of BOX_FACES) {
			faces.push({ vertIndices: f.verts.map(ii => voff + ii), tone: f.tone });
		}
	}
	return { vertices, faces };
}

function getStackedGeometry(block) {
	const p = block.pos;
	const w = block.size.x, h = block.size.y, d = block.size.z;
	const { botFrac, sizeFrac } = block._structParams;
	const topFrac = 1 - botFrac;
	const botPos = createVector(p.x, p.y - h * (topFrac / 2), p.z);
	const topPos = createVector(p.x, p.y + h * (topFrac / 2), p.z);
	const botSz = createVector(w / 2, h * botFrac / 2, d / 2);
	const topSz = createVector(w * sizeFrac / 2, h * topFrac / 2, d * sizeFrac / 2);
	const v0 = boxVerts(botPos, botSz.x, botSz.y, botSz.z);
	const v1 = boxVerts(topPos, topSz.x, topSz.y, topSz.z);
	const vertices = [...v0, ...v1];
	const faces = [];
	for (const f of BOX_FACES) faces.push({ vertIndices: [...f.verts], tone: f.tone });
	for (const f of BOX_FACES) faces.push({ vertIndices: f.verts.map(i => 8 + i), tone: f.tone * 1.05 });
	return { vertices, faces };
}

function getSplitGeometry(block) {
	const p = block.pos;
	const w = block.size.x, h = block.size.y, d = block.size.z;
	const { splitAxis, frac } = block._structParams;
	let pos1, pos2, sz1, sz2;
	if (splitAxis === "x") {
		const w1 = w * frac, w2 = w * (1 - frac);
		pos1 = createVector(p.x - w * (1 - frac) / 2, p.y, p.z);
		pos2 = createVector(p.x + w * frac / 2, p.y, p.z);
		sz1 = createVector(w1 / 2, h / 2, d / 2);
		sz2 = createVector(w2 / 2, h / 2, d / 2);
	} else {
		const d1 = d * frac, d2 = d * (1 - frac);
		pos1 = createVector(p.x, p.y, p.z - d * (1 - frac) / 2);
		pos2 = createVector(p.x, p.y, p.z + d * frac / 2);
		sz1 = createVector(w / 2, h / 2, d1 / 2);
		sz2 = createVector(w / 2, h / 2, d2 / 2);
	}
	const v0 = boxVerts(pos1, sz1.x, sz1.y, sz1.z);
	const v1 = boxVerts(pos2, sz2.x, sz2.y, sz2.z);
	const vertices = [...v0, ...v1];
	const faces = [];
	for (const f of BOX_FACES) faces.push({ vertIndices: [...f.verts], tone: f.tone });
	for (const f of BOX_FACES) faces.push({ vertIndices: f.verts.map(i => 8 + i), tone: f.tone * 0.95 });
	return { vertices, faces };
}

/** Tunnel: box with two opposing faces removed (front/back or left/right). */
function getTunnelGeometry(block) {
	const p = block.pos;
	const sx = block.size.x / 2, sy = block.size.y / 2, sz = block.size.z / 2;
	const verts = boxVerts(p, sx, sy, sz);
	const { axis } = block._structParams;
	const faces = [];
	if (axis === "z") {
		for (const i of [0, 1, 4, 5]) faces.push({ vertIndices: [...BOX_FACES[i].verts], tone: BOX_FACES[i].tone });
	} else {
		for (const i of [0, 1, 2, 3]) faces.push({ vertIndices: [...BOX_FACES[i].verts], tone: BOX_FACES[i].tone });
	}
	return { vertices: verts, faces };
}

/** Protruding: main block + smaller walls sticking out on 2–4 lateral sides. */
function getProtrudingGeometry(block) {
	const p = block.pos;
	const w = block.size.x, h = block.size.y, d = block.size.z;
	const sx = w / 2, sy = h / 2, sz = d / 2;
	const { nSides, wallFrac, protrudeFrac } = block._structParams;
	const sides = shuffle(["nz", "pz", "nx", "px"], true).slice(0, nSides);
	const protrudeD = Math.min(w, d) * protrudeFrac;
	const wallW = w * wallFrac;
	const wallH = h * wallFrac;

	const vertices = [];
	const faces = [];
	vertices.push(...boxVerts(p, sx, sy, sz));
	for (const f of BOX_FACES) faces.push({ vertIndices: [...f.verts], tone: f.tone });
	let voff = 8;

	for (const side of sides) {
		let pos, hw, hh, hd;
		if (side === "nz") {
			pos = createVector(p.x, p.y, p.z - sz - protrudeD / 2);
			hw = wallW / 2; hh = wallH / 2; hd = protrudeD / 2;
		} else if (side === "pz") {
			pos = createVector(p.x, p.y, p.z + sz + protrudeD / 2);
			hw = wallW / 2; hh = wallH / 2; hd = protrudeD / 2;
		} else if (side === "nx") {
			pos = createVector(p.x - sx - protrudeD / 2, p.y, p.z);
			hw = protrudeD / 2; hh = wallH / 2; hd = wallW / 2;
		} else {
			pos = createVector(p.x + sx + protrudeD / 2, p.y, p.z);
			hw = protrudeD / 2; hh = wallH / 2; hd = wallW / 2;
		}
		const v = boxVerts(pos, hw, hh, hd);
		vertices.push(...v);
		for (const f of BOX_FACES) faces.push({ vertIndices: f.verts.map(i => voff + i), tone: f.tone * 0.98 });
		voff += 8;
	}
	return { vertices, faces };
}

function getHollowWindowGeometry(block) {
	const p = block.pos;
	const sx = block.size.x / 2, sy = block.size.y / 2, sz = block.size.z / 2;
	const verts = boxVerts(p, sx, sy, sz);
	const { winW, winH } = block._structParams;
	const wcx = p.x, wcy = p.y, wcz = p.z - sz - 0.01;
	const hw = winW / 2, hh = winH / 2;
	const holeVerts = [
		createVector(wcx - hw, wcy - hh, wcz),
		createVector(wcx + hw, wcy - hh, wcz),
		createVector(wcx + hw, wcy + hh, wcz),
		createVector(wcx - hw, wcy + hh, wcz),
	];
	verts.push(...holeVerts);
	const faces = [];
	for (let i = 0; i < BOX_FACES.length; i++) {
		if (i === 2) {
			faces.push({ vertIndices: [0, 1, 5, 4], tone: BOX_FACES[i].tone, holeIndices: [8, 9, 10, 11] });
		} else {
			faces.push({ vertIndices: BOX_FACES[i].verts, tone: BOX_FACES[i].tone });
		}
	}
	return { vertices: verts, faces };
}

function faceDepthFromVerts(vertices, face) {
	const v = face.vertIndices;
	const c = v.reduce((acc, i) => acc.add(vertices[i]), createVector(0, 0, 0));
	c.div(v.length);
	const scaled = createVector(c.x * worldScale, c.y * worldScale, c.z * worldScale);
	const p = cameraSpace(scaled, cam.yaw);
	return p.z + camDist;
}

function faceNormalWorld(vertices, face) {
	const idx = face.vertIndices;
	const v0 = vertices[idx[0]];
	const v1 = vertices[idx[1]];
	const v2 = vertices[idx[2]];
	const e1 = p5.Vector.sub(v1, v0);
	const e2 = p5.Vector.sub(v2, v0);
	return p5.Vector.cross(e1, e2).normalize();
}

function faceCenterWorld(vertices, face) {
	const idx = face.vertIndices;
	const c = idx.reduce((acc, i) => acc.add(vertices[i]), createVector(0, 0, 0));
	c.div(idx.length);
	return c;
}

function getLightFactor(faceCenter, faceNormal) {
	const azim = params.lightAzim * TWO_PI;
	const elev = params.lightElev * HALF_PI;
	const _dst = params.lightDistance;
	const sceneCenterY = (worldMinY + worldMaxY) / 2;
	const lx = _dst * cos(elev) * cos(azim);
	const ly = sceneCenterY + _dst * sin(elev);
	const lz = _dst * cos(elev) * sin(azim);
	const lightPos = createVector(lx, ly, lz);
	const toLight = p5.Vector.sub(lightPos, faceCenter).normalize();
	const _dot = p5.Vector.dot(faceNormal, toLight);
	const diffuse = Math.max(0, _dot);
	return params.lightAmbient + (1 - params.lightAmbient) * diffuse;
}

function faceNormalInCameraSpace(vertices, face) {
	const n = faceNormalWorld(vertices, face);
	const scaled = createVector(n.x * worldScale, n.y * worldScale, n.z * worldScale);
	return cameraSpace(scaled, cam.yaw).normalize();
}

function isBackFace(vertices, face) {
	const n = faceNormalInCameraSpace(vertices, face);
	return n.z > 0;
}

/** Returns { watercolor: bool, hatching: bool, subdivision: bool } - independent probabilities. */
function pickTextures() {
	return {
		watercolor: random() < params.textureWatercolor,
		hatching: random() < params.textureHatching,
		subdivision: random() < params.textureSubdivision,
	};
}

/** Uniform random point in triangle (A,B,C). */
function randomPointInTriangle(A, B, C) {
	let u = random(), v = random();
	if (u + v > 1) { u = 1 - u; v = 1 - v; }
	return p5.Vector.add(A, p5.Vector.add(
		p5.Vector.mult(p5.Vector.sub(B, A), u),
		p5.Vector.mult(p5.Vector.sub(C, A), v)
	));
}

/** Signed area of triangle (×2). */
function triangleArea2(A, B, C) {
	return (B.x - A.x) * (C.y - A.y) - (C.x - A.x) * (B.y - A.y);
}

/** Uniform random point in convex quad (A,B,C,D) vertices in order. */
function randomPointInQuad(A, B, C, D) {
	const area1 = abs(triangleArea2(A, B, C));
	const area2 = abs(triangleArea2(A, C, D));
	const total = area1 + area2;
	if (total < 1e-9) return A.copy();
	if (random() < area1 / total) return randomPointInTriangle(A, B, C);
	return randomPointInTriangle(A, C, D);
}

/** Uniform random point in convex polygon (3+ vertices). */
function randomPointInPoly(poly) {
	if (poly.length < 3) return poly[0]?.copy() || createVector(0, 0);
	if (poly.length === 3) return randomPointInTriangle(poly[0], poly[1], poly[2]);
	if (poly.length === 4) return randomPointInQuad(poly[0], poly[1], poly[2], poly[3]);
	let totalArea = 0;
	const areas = [];
	for (let i = 1; i < poly.length - 1; i++) {
		const a = abs(triangleArea2(poly[0], poly[i], poly[i + 1]));
		areas.push(a);
		totalArea += a;
	}
	let r = random(totalArea);
	for (let i = 0; i < areas.length; i++) {
		r -= areas[i];
		if (r <= 0) return randomPointInTriangle(poly[0], poly[i + 1], poly[i + 2]);
	}
	return randomPointInTriangle(poly[0], poly[1], poly[2]);
}

/** Expand polygon vertices outward by margin. */
function expandPolyByMargin(poly, margin) {
	const n = poly.length;
	if (n < 3) return poly;
	const cx = poly.reduce((s, p) => s + p.x, 0) / n;
	const cy = poly.reduce((s, p) => s + p.y, 0) / n;
	return poly.map(p => {
		const dx = p.x - cx, dy = p.y - cy;
		const len = sqrt(dx * dx + dy * dy) || 1;
		return createVector(p.x + (dx / len) * margin, p.y + (dy / len) * margin);
	});
}

function getLightPositionWorld() {
	const azim = params.lightAzim * TWO_PI;
	const elev = params.lightElev * HALF_PI;
	const sceneCenterY = (worldMinY + worldMaxY) / 2;
	const d = params.lightDistance;
	return createVector(
		d * cos(elev) * cos(azim),
		sceneCenterY + d * sin(elev),
		d * cos(elev) * sin(azim)
	);
}

/** Intersection of line (all pts q where dot(q, perp) = pVal) with polygon. Returns points sorted along dir. */
function linePolygonIntersect(poly, perp, pVal, dir) {
	const out = [];
	const n = poly.length;
	for (let i = 0; i < n; i++) {
		const j = (i + 1) % n;
		const a = poly[i], b = poly[j];
		const va = a.x * perp.x + a.y * perp.y;
		const vb = b.x * perp.x + b.y * perp.y;
		if ((va <= pVal && pVal <= vb) || (vb <= pVal && pVal <= va)) {
			if (vb !== va) {
				const t = (pVal - va) / (vb - va);
				out.push(createVector(a.x + t * (b.x - a.x), a.y + t * (b.y - a.y)));
			}
		}
	}
	out.sort((p, q) => (p.x * dir.x + p.y * dir.y) - (q.x * dir.x + q.y * dir.y));
	return out;
}

/** Split quad [A,B,C,D] by line perp·p = pVal. Returns [poly1, poly2] or null if not exactly 2 intersections. */
function splitQuadByLine(quad, perp, pVal) {
	const n = quad.length;
	const projs = quad.map(p => p.x * perp.x + p.y * perp.y);
	const part0 = [], part1 = [];
	let current = projs[0] < pVal ? 0 : 1;
	for (let i = 0; i < n; i++) {
		const j = (i + 1) % n;
		const va = projs[i], vb = projs[j];
		(current === 0 ? part0 : part1).push(quad[i]);
		const crosses = (va < pVal && vb > pVal) || (va > pVal && vb < pVal);
		if (crosses && vb !== va) {
			const t = (pVal - va) / (vb - va);
			const pt = createVector(quad[i].x + t * (quad[j].x - quad[i].x), quad[i].y + t * (quad[j].y - quad[i].y));
			(current === 0 ? part0 : part1).push(pt);
			current = 1 - current;
			(current === 0 ? part0 : part1).push(pt);
		}
	}
	if (part0.length < 3 || part1.length < 3) return null;
	return [part0, part1];
}

/** Apply subdivision texture: recursive parallelogram subdivision (0.3–0.7), up to 3 levels, either direction. */
function applySubdivisionTexture(geom, face, projected) {
	const order = isBackFace(geom.vertices, face) ? [...face.vertIndices].reverse() : face.vertIndices;
	const poly = order.map(i => projected[i]);
	if (poly.length !== 4) return;
	const lines = [];
	subdivideQuadRec(poly, params.subdivisionDepth, lines);
	push();
	beginClip();
	beginShape();
	for (const p of poly) vertex(p.x, p.y);
	if (face.holeIndices) {
		beginContour();
		if (isBackFace(geom.vertices, face)) {
			for (const j of face.holeIndices) vertex(projected[j].x, projected[j].y);
		} else {
			for (let i = face.holeIndices.length - 1; i >= 0; i--) {
				vertex(projected[face.holeIndices[i]].x, projected[face.holeIndices[i]].y);
			}
		}
		endContour();
	}
	endShape(CLOSE);
	endClip();
	const hsb = hexToHSB(SUBDIVISION_LINE_COLOR);
	stroke(hsb.h, hsb.s, hsb.b, 0.8);
	strokeWeight(params.subdivisionLineWeight);
	noFill();
	for (const [a, b] of lines) {
		line(a.x, a.y, b.x, b.y);
	}
	noStroke();
	pop();
}

/**
 * Returns { h, s, b } for a surface. Uses palette colors.
 */
function getSurfaceColor(opts) {
	return hexToHSB(random(PALETTE_COLORS));
}

// -----------------------------------------------------------------------------
// Projection
// -----------------------------------------------------------------------------

function project(pt) {
	const scaled = createVector(pt.x * worldScale, pt.y * worldScale, pt.z * worldScale);
	const p = projectPoint(scaled, cam, camDist, eyeY);
	if (!p) return null;
	const dx = (p.x - structureCenterX) * projScale;
	const dy = (p.y - structureCenterY) * projScale;
	return createVector(width / 2 + dx, height / 2 + dy);
}

function blockDepth(block) {
	const scaled = createVector(block.pos.x * worldScale, block.pos.y * worldScale, block.pos.z * worldScale);
	const p = cameraSpace(scaled, cam.yaw);
	return p.z + camDist;
}

function solveCameraFromVPs(vpLx, vpRx, hY) {
	const cx = width / 2;
	const a = vpRx - cx;
	const b = vpLx - cx;
	const eps = 1e-6;
	let aa = (abs(a) < eps) ? (a >= 0 ? eps : -eps) : a;
	let bb = (abs(b) < eps) ? (b >= 0 ? eps : -eps) : b;
	if (aa * bb > 0) { aa = abs(aa); bb = -abs(bb); }
	const f = sqrt(Math.max(1, -aa * bb));
	// const tanTheta = max(0.05, min(20, -bb / f));
	const tanTheta = constrain((-bb / f), 0.05, 20.0);
	const yaw = Math.atan(tanTheta);
	return { f, yaw, cx, horizonY: hY };
}

function cameraSpace(p, yaw) {
	const c = cos(yaw);
	const s = sin(yaw);
	const x = p.x * c + p.z * s;
	const z = -p.x * s + p.z * c;
	return createVector(x, p.y, z);
}

function projectPoint(pWorld, cam, dist, eyeY = 0) {
	const p = cameraSpace(pWorld, cam.yaw);
	const Z = p.z + dist;
	if (Z < 10) return null;
	const x = cam.cx + cam.f * (p.x / Z);
	// eyeY = world Y at camera/eye level; points here project to the horizon
	const y = cam.horizonY + cam.f * ((p.y - eyeY) / Z);
	return createVector(x, y);
}

function computeStructureBounds() {
	worldMinY = Infinity;
	worldMaxY = -Infinity;
	for (const block of blocks) {
		const geom = getStructureGeometry(block);
		for (const c of geom.vertices) {
			worldMinY = Math.min(worldMinY, c.y);
			worldMaxY = Math.max(worldMaxY, c.y);
		}
	}
	if (worldMinY === Infinity) worldMinY = worldMaxY = 0;
}

function computeFitAndCenter() {
	let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
	for (const block of blocks) {
		const geom = getStructureGeometry(block);
		for (const c of geom.vertices) {
			const scaled = createVector(c.x * worldScale, c.y * worldScale, c.z * worldScale);
			const p = projectPoint(scaled, cam, camDist, eyeY);
			if (p) {
				minX = Math.min(minX, p.x);
				maxX = Math.max(maxX, p.x);
				minY = Math.min(minY, p.y);
				maxY = Math.max(maxY, p.y);
			}
		}
	}
	if (minX === Infinity) return;
	structureCenterX = (minX + maxX) / 2;
	structureCenterY = (minY + maxY) / 2;
	const spanX = maxX - minX;
	const spanY = maxY - minY;
	projScale = Math.min((width * 0.9) / spanX, (height * 0.9) / spanY);
}

// -----------------------------------------------------------------------------
// Structure generation
// -----------------------------------------------------------------------------

function generateStructure(cfg) {
	const unit = cfg.unit;
	const coreBlocks = [];
	const all = [];
	const anchors = [];

	function addBlock(block) {
		if (block.kind === "beam" || block.kind === "satellite") {
			block.structureKind = "box";
		} else {
			block.structureKind = pickStructureKind();
			if (block.structureKind !== "box") {
				block._structParams = makeStructParams(block);
			}
		}
		all.push(block);
		const w = block.size.x;
		const h = block.size.y;
		const d = block.size.z;
		const faceWeight = block.kind === "core" ? 1.0 : 0.8;
		const allowFaces = (block.kind !== "beam") && (block.kind !== "micro");

		if (allowFaces) {
			anchors.push(makeAnchor(block, "px", faceWeight * 1.0));
			anchors.push(makeAnchor(block, "nx", faceWeight * 1.0));
			anchors.push(makeAnchor(block, "pz", faceWeight * 1.0));
			anchors.push(makeAnchor(block, "nz", faceWeight * 1.0));
			if (random() < 0.35) anchors.push(makeAnchor(block, "py", faceWeight * 0.7));
		}
	}

	let yCursor = 0;
	let coreX = 0;
	let coreZ = 0;
	const coreW = cfg.coreW * unit;
	const coreD = cfg.coreD * unit;

	for (let i = 0; i < cfg.coreCount; i++) {
		const h = random(cfg.coreMinH, cfg.coreMaxH) * unit;
		coreX += random(-0.25, 0.25) * unit;
		coreZ += random(-0.25, 0.25) * unit;
		const w = coreW * random(0.85, 1.15);
		const d = coreD * random(0.85, 1.15);

		const block = makeBlock(
			createVector(coreX, -yCursor - h / 2, coreZ),
			createVector(w, h, d),
			{ kind: "core", tone: random(170, 220) }
		);
		block.pos.x = snap(block.pos.x, unit * 0.25);
		block.pos.z = snap(block.pos.z, unit * 0.25);
		addBlock(block);
		coreBlocks.push(block);
		yCursor += h;
	}

	const targetCount = cfg.maxBlocks;
	let tries = 0;
	let _wG_1 = 0; while ((all.length < targetCount && tries < targetCount * 50) && ++_wG_1 < 20000) {
		tries++;
		const a = pickWeightedAnchor(anchors);
		if (!a) break;

		const early = all.length < targetCount * 0.55;
		const mustBeCore = early && random() < 0.65;
		if (mustBeCore && a.block.kind !== "core") continue;

		const b = proposeAttachment(a, unit, cfg);
		if (isBadOverlap(b, all)) continue;
		addBlock(b);

		if (random() < cfg.wildChance) {
			const beam = proposeBeamFrom(b, unit);
			if (!isBadOverlap(beam, all)) addBlock(beam);
		}
		if (random() < cfg.satelliteChance) {
			const sat = proposeSatelliteNear(b, unit);
			if (!isBadOverlap(sat, all)) addBlock(sat);
		}
	}

	return all;
}

function proposeAttachment(anchor, unit, cfg) {
	const base = anchor.block;
	const style = random();
	let w, h, d, kind;

	if (style < 0.55) {
		w = random(1.2, 3.2) * unit;
		h = random(0.9, 2.2) * unit;
		d = random(1.2, 3.2) * unit;
		kind = "room";
	} else if (style < 0.85) {
		w = random(2.5, 5.2) * unit;
		h = random(0.55, 1.1) * unit;
		d = random(1.2, 2.6) * unit;
		kind = "slab";
	} else {
		w = random(0.6, 1.4) * unit;
		h = random(0.6, 1.8) * unit;
		d = random(0.6, 1.4) * unit;
		kind = "micro";
	}

	const pos = attachPos(base, createVector(w, h, d), anchor.face);
	const slide = unit * random(-1.5, 1.5);
	const slide2 = unit * random(-1.5, 1.5);

	if (anchor.face === "px" || anchor.face === "nx") {
		pos.z += slide;
		pos.y += slide2 * 0.35;
	} else if (anchor.face === "pz" || anchor.face === "nz") {
		pos.x += slide;
		pos.y += slide2 * 0.35;
	} else if (anchor.face === "py") {
		pos.x += slide;
		pos.z += slide2;
	}

	if (random() < 0.22) {
		const _push = unit * random(0.6, 2.8);
		if (anchor.face === "px") pos.x += _push;
		if (anchor.face === "nx") pos.x -= _push;
		if (anchor.face === "pz") pos.z += _push;
		if (anchor.face === "nz") pos.z -= _push;
	}

	pos.x = snap(pos.x, unit * 0.25);
	pos.y = snap(pos.y, unit * 0.25);
	pos.z = snap(pos.z, unit * 0.25);

	return makeBlock(pos, createVector(w, h, d), { kind, tone: random(165, 235) });
}

function proposeBeamFrom(block, unit) {
	const face = random(["px", "nx", "pz", "nz"]);
	const along = random() < 0.5 ? "x" : "z";

	let w = random(0.4, 0.9) * unit;
	let h = random(0.25, 0.55) * unit;
	let d = random(0.4, 0.9) * unit;
	const L = random(3.0, 8.0) * unit;
	if (along === "x") w = L;
	else d = L;

	const pos = attachPos(block, createVector(w, h, d), face);
	pos.y += random(-0.7, 0.7) * unit;
	pos.x = snap(pos.x, unit * 0.25);
	pos.y = snap(pos.y, unit * 0.25);
	pos.z = snap(pos.z, unit * 0.25);

	return makeBlock(pos, createVector(w, h, d), { kind: "beam", tone: random(150, 210) });
}

function proposeSatelliteNear(block, unit) {
	const w = block.size.x * random(0.5, 0.95);
	const h = block.size.y * random(0.45, 0.85);
	const d = block.size.z * random(0.5, 0.95);

	const pos = block.pos.copy();
	const dir = p5.Vector.random3D();
	dir.y *= 0.25;
	dir.normalize();
	const _dist = random(0.6, 2.0) * unit + Math.max(w, d) * 0.35;
	pos.add(dir.mult(_dist));

	if (random() < 0.5) pos.x = block.pos.x;
	else pos.z = block.pos.z;

	pos.x = snap(pos.x, unit * 0.25);
	pos.y = snap(pos.y, unit * 0.25);
	pos.z = snap(pos.z, unit * 0.25);

	return makeBlock(pos, createVector(w, h, d), { kind: "satellite", tone: random(160, 225) });
}

function makeBlock(pos, size, meta = {}) {
	return {
		pos,
		size,
		kind: meta.kind ?? "room",
		tone: meta.tone ?? 200,
	};
}

function makeAnchor(block, face, weight) {
	let w = weight;
	if (block.kind === "core") w *= 2.0;
	if (block.kind === "slab") w *= 0.85;
	if (block.kind === "beam") w *= 0.25;
	return { block, face, w };
}

function pickWeightedAnchor(anchors) {
	if (anchors.length > 2000 && random() < 0.15) {
		anchors.splice(0, floor(anchors.length * 0.25));
	}
	let sum = 0;
	for (const a of anchors) sum += a.w;
	if (sum <= 0) return null;
	let r = random(sum);
	for (const a of anchors) {
		r -= a.w;
		if (r <= 0) return a;
	}
	return anchors[anchors.length - 1] ?? null;
}

function attachPos(base, newSize, face) {
	const p = base.pos.copy();
	if (face === "px") p.x = base.pos.x + base.size.x / 2 + newSize.x / 2;
	if (face === "nx") p.x = base.pos.x - base.size.x / 2 - newSize.x / 2;
	if (face === "pz") p.z = base.pos.z + base.size.z / 2 + newSize.z / 2;
	if (face === "nz") p.z = base.pos.z - base.size.z / 2 - newSize.z / 2;
	if (face === "py") p.y = base.pos.y - base.size.y / 2 - newSize.y / 2;
	if (face !== "py") p.y += random(-0.35, 0.35) * Math.min(base.size.y, newSize.y) * 0.25;
	return p;
}

function isBadOverlap(candidate, existing) {
	for (const b of existing) {
		const inter = intersectionAABB(candidate, b);
		if (!inter) continue;
		const vI = inter.x * inter.y * inter.z;
		const vC = candidate.size.x * candidate.size.y * candidate.size.z;
		const vB = b.size.x * b.size.y * b.size.z;
		if (vI / vC > 0.60) { return true; }
		if (vI / Math.min(vC, vB) > 0.92) { return true; }
	}
	const limit = 900;
	if (abs(candidate.pos.x) > limit || abs(candidate.pos.y) > 1200 || abs(candidate.pos.z) > limit) return true;
	return false;
}

function intersectionAABB(a, b) {
	const ax0 = a.pos.x - a.size.x / 2, ax1 = a.pos.x + a.size.x / 2;
	const ay0 = a.pos.y - a.size.y / 2, ay1 = a.pos.y + a.size.y / 2;
	const az0 = a.pos.z - a.size.z / 2, az1 = a.pos.z + a.size.z / 2;
	const bx0 = b.pos.x - b.size.x / 2, bx1 = b.pos.x + b.size.x / 2;
	const by0 = b.pos.y - b.size.y / 2, by1 = b.pos.y + b.size.y / 2;
	const bz0 = b.pos.z - b.size.z / 2, bz1 = b.pos.z + b.size.z / 2;
	const ix0 = Math.max(ax0, bx0), ix1 = Math.min(ax1, bx1);
	const iy0 = Math.max(ay0, by0), iy1 = Math.min(ay1, by1);
	const iz0 = Math.max(az0, bz0), iz1 = Math.min(az1, bz1);
	if (ix1 <= ix0 || iy1 <= iy0 || iz1 <= iz0) return null;
	return createVector(ix1 - ix0, iy1 - iy0, iz1 - iz0);
}

function snap(v, step) {
	return round(v / step) * step;
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

